async function retryWithBackoff(fn, { retries = 3, baseDelay = 100, maxDelay = 2000 } = {}) {
  let lastError;
  for (let attempt = 0; attempt <= retries; attempt++) {
    try {
      return await fn(); // 成功立即返回，不再重试
    } catch (err) {
      lastError = err;
      if (attempt === retries) break; // 重试用尽，跳出后抛错
      const expo = Math.min(maxDelay, baseDelay * 2 ** attempt);
      const jitter = 0.5 + Math.random(); // 0.5 ~ 1.5 的随机系数
      const delay = Math.floor(expo * jitter);
      console.log(`第 ${attempt + 1} 次失败，${delay}ms 后重试:`, err.message);
      await new Promise((resolve) => setTimeout(resolve, delay));
    }
  }
  throw lastError;
}

