let calls = 0;
const flaky = () =>
  new Promise((resolve, reject) => {
    calls++;
    setTimeout(() => (calls < 3 ? reject(new Error('transient')) : resolve('ok-' + calls)), 10);
  });
retryWithBackoff(flaky, { retries: 3, baseDelay: 50, maxDelay: 500 }).then((r) => {
  console.log('测试1结果:', r, '总调用次数:', calls); // ok-3，3

  // ---- 测试 2：始终失败，验证最终抛错 ----
  let calls2 = 0;
  const alwaysFail = () => {
    calls2++;
    return Promise.reject(new Error('boom'));
  };
  return retryWithBackoff(alwaysFail, { retries: 2, baseDelay: 20, maxDelay: 200 })
    .then(() => console.log('不应走到这里'))
    .catch((e) => console.log('测试2最终错误:', e.message, '总调用次数:', calls2)); // boom，3
});
